static inline uint32_t mpu_rasr_a1_size_get(void) { return (MPU.RASR_A1 & MPU_RASR_A1_SIZE) >> 1; }
static inline void mpu_rasr_a1_srd_set(uint32_t val) { MPU.RASR_A1 = (MPU.RASR_A1 & ~MPU_RASR_A1_SRD) | ((val<<8) & MPU_RASR_A1_SRD); }
static inline uint32_t mpu_rasr_a1_srd_get(void) { return (MPU.RASR_A1 & MPU_RASR_A1_SRD) >> 8; }
static inline void mpu_rasr_a1_tex_set(uint32_t val) { MPU.RASR_A1 = (MPU.RASR_A1 & ~MPU_RASR_A1_TEX) | ((val<<19) & MPU_RASR_A1_TEX); }
static inline uint32_t mpu_rasr_a1_tex_get(void) { return (MPU.RASR_A1 & MPU_RASR_A1_TEX) >> 19; }
static inline void mpu_rasr_a1_ap_set(uint32_t val) { MPU.RASR_A1 = (MPU.RASR_A1 & ~MPU_RASR_A1_AP) | ((val<<24) & MPU_RASR_A1_AP); }
static inline uint32_t mpu_rasr_a1_ap_get(void) { return (MPU.RASR_A1 & MPU_RASR_A1_AP) >> 24; }

