static inline uint32_t scb_aircr_prigroup_get(void) { return (SCB.AIRCR & SCB_AIRCR_PRIGROUP) >> 8; }
static inline void scb_aircr_vectkey_set(uint32_t val) { SCB.AIRCR = (SCB.AIRCR & ~SCB_AIRCR_VECTKEY) | ((val<<16) & SCB_AIRCR_VECTKEY); }
static inline uint32_t scb_aircr_vectkey_get(void) { return (SCB.AIRCR & SCB_AIRCR_VECTKEY) >> 16; }

// SCB->SCR System control register
enum {
	SCB_SCR_SLEEPONEXIT = 0x2, // Sleep on return from ISR
	SCB_SCR_SLEEPDEEP = 0x4, // Deep sleep enable
	SCB_SCR_SEVONPEND = 0x10, // Send event on pending
};

// SCB->CCR Configuration and control register
enum {
	SCB_CCR_NONBASETHRDENA = 0x1, // Allow Thread mode from any level
	SCB_CCR_USERSETMPEND = 0x2, // Enable unprivileged STIR access
	SCB_CCR_UNALIGN_TRP = 0x8, // Trap unaligned access
	SCB_CCR_DIV_0_TRP = 0x10, // Trap divide by zero
	SCB_CCR_BFHFNMIGN = 0x100, // Ignore bus faults in NMI/HardFault
	SCB_CCR_STKALIGN = 0x200, // 8-byte stack alignment
};

