static inline uint32_t ucpd_cfg1_psc_usbpdclk_get(void) { return (UCPD.CFG1 & UCPD_CFG1_PSC_USBPDCLK) >> 17; }
static inline void ucpd_cfg1_rxordseten_set(uint32_t val) { UCPD.CFG1 = (UCPD.CFG1 & ~UCPD_CFG1_RXORDSETEN) | ((val<<20) & UCPD_CFG1_RXORDSETEN); }
